def aplicar(apps, schema_editor):
    Special = apps.get_model("generate", "Special")

    for pk, _n, _viejo, nuevo in LIMPIAR:
        s = Special.objects.filter(pk=pk).first()
        if s is not None:
            s.prompt = nuevo
            s.save(update_fields=["prompt"])

    for nombre, prompt in ONLY + SEDUCT:
        if Special.objects.filter(name=nombre).exists():
            continue
        Special.objects.create(name=nombre, tier="tier3", prompt=prompt)


def revertir(apps, schema_editor):
    Special = apps.get_model("generate", "Special")

    Special.objects.filter(
        name__in=[x[0] for x in ONLY + SEDUCT]
    ).delete()

    for pk, _n, viejo, _nuevo in LIMPIAR:
        s = Special.objects.filter(pk=pk).first()
        if s is not None:
            s.prompt = viejo
            s.save(update_fields=["prompt"])


